#!/usr/bin/env python3
import json
import os
import sys
import time


USAGE = "usage: wait-log [after-seq] [timeout-seconds] [poll-seconds]"


def events_from(lines):
    events = []
    for line in lines:
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(event.get("seq"), int):
            events.append(event)
    return events


if len(sys.argv) > 4:
    print(USAGE, file=sys.stderr)
    raise SystemExit(2)

initial = events_from(sys.stdin)
try:
    after = int(sys.argv[1]) if len(sys.argv) > 1 else max((event["seq"] for event in initial), default=0)
    timeout = float(sys.argv[2]) if len(sys.argv) > 2 else 600.0
    poll = float(sys.argv[3]) if len(sys.argv) > 3 else 0.25
except ValueError:
    print(USAGE, file=sys.stderr)
    raise SystemExit(2)

if after < 0 or timeout <= 0 or poll <= 0:
    print(USAGE, file=sys.stderr)
    raise SystemExit(2)

path = os.path.join(os.environ["SELF_HOME"], "events.jsonl")
deadline = time.monotonic() + timeout

while True:
    try:
        with open(path, encoding="utf-8") as stream:
            new_events = [event for event in events_from(stream) if event["seq"] > after]
    except FileNotFoundError:
        new_events = []

    if new_events:
        summaries = []
        for event in new_events[:100]:
            payload = event.get("payload", {})
            summaries.append(
                {
                    "seq": event["seq"],
                    "name": event.get("name"),
                    "by": event.get("by"),
                    "goal": payload.get("goal") if isinstance(payload, dict) else None,
                }
            )
        print(
            json.dumps(
                {
                    "name": "log.advance_observed",
                    "payload": {
                        "after": after,
                        "through": max(event["seq"] for event in new_events),
                        "count": len(new_events),
                        "truncated": len(new_events) > 100,
                        "events": summaries,
                    },
                },
                separators=(",", ":"),
            )
        )
        raise SystemExit(0)

    if time.monotonic() >= deadline:
        print(f"wait-log: no event after seq {after} within {timeout:g}s", file=sys.stderr)
        raise SystemExit(124)
    time.sleep(poll)

#!/usr/bin/env python3
import json
import os
import sys
import time


USAGE = (
    "usage: wait-log [after-seq|-] [timeout-seconds] [poll-seconds] [filter...]\n"
    "  filters: name:<substr> by:<substr> goal:<substr> or bare <substr> (any field);\n"
    "  OR within a kind, AND across kinds. log.advance_observed receipts never trigger."
)


