    events = []
    for line in lines:
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(event.get("seq"), int):
            events.append(event)
    return events


def fields(event):
    payload = event.get("payload", {})
    return {
        "name": str(event.get("name") or ""),
        "by": str(event.get("by") or ""),
        "goal": str(payload.get("goal") or "") if isinstance(payload, dict) else "",
    }


def parse_filters(tokens):
    groups = {}
    for token in tokens:
        kind, _, value = token.partition(":")
        if kind in ("name", "by", "goal") and value:
            groups.setdefault(kind, []).append(value)
        elif token:
            groups.setdefault("any", []).append(token)
    return groups


def matches(event, groups):
    got = fields(event)
    if got["name"] == "log.advance_observed":
        return False
    for kind, values in groups.items():
        if kind == "any":
            if not any(v in got["name"] or v in got["by"] or v in got["goal"] for v in values):
                return False
        elif not any(v in got[kind] for v in values):
            return False
    return True


