args = sys.argv[1:]
try:
    after_arg = args[0] if args else "-"
    after = max((event["seq"] for event in initial), default=0) if after_arg in ("", "-") else int(after_arg)
    timeout = float(args[1]) if len(args) > 1 else 600.0
    poll = float(args[2]) if len(args) > 2 else 0.25
except ValueError:
    print(USAGE, file=sys.stderr)
    raise SystemExit(2)

if after < 0 or timeout <= 0 or poll <= 0:
    print(USAGE, file=sys.stderr)
    raise SystemExit(2)

groups = parse_filters(args[3:])

path = os.path.join(os.environ["SELF_HOME"], "events.jsonl")
deadline = time.monotonic() + timeout

while True:
    try:
        with open(path, encoding="utf-8") as stream:
            new_events = [
                event
                for event in events_from(stream)
                if event["seq"] > after and matches(event, groups)
            ]
    except FileNotFoundError:
        new_events = []

    if new_events:
        summaries = []
        for event in new_events[:100]:
            payload = event.get("payload", {})
            summaries.append(
                {
                    "seq": event["seq"],
                    "name": event.get("name"),
                    "by": event.get("by"),
                    "goal": payload.get("goal") if isinstance(payload, dict) else None,
                }
            )
        receipt = {
            "after": after,
            "through": max(event["seq"] for event in new_events),
            "count": len(new_events),
            "truncated": len(new_events) > 100,
            "events": summaries,
        }
        if groups:
            receipt["filters"] = [
                f"{kind}:{value}" if kind != "any" else value
                for kind, values in sorted(groups.items())
                for value in values
            ]
        print(json.dumps({"name": "log.advance_observed", "payload": receipt}, separators=(",", ":")))
        raise SystemExit(0)

    if time.monotonic() >= deadline:
        print(f"wait-log: no matching event after seq {after} within {timeout:g}s", file=sys.stderr)
        raise SystemExit(124)
    time.sleep(poll)

